// O node "Gerar link da foto" (HTTP Request) troca o conteúdo do item
// pela resposta da API (só sobra signedURL) — os campos originais
// (nome_cliente, produtos, data, registrado_por, dias_aberta) vêm do
// node "Tem foto?" de propósito, não do input direto deste node.
const original = $('Tem foto?').item.json;
const item = $input.item.json;

// Postgres do n8n devolve coluna `date` como timestamp completo
// ("2026-08-09T00:00:00.000Z"), não só "2026-08-09" — corta os 10
// primeiros caracteres antes de separar, funciona pros dois formatos.
function fmtData(iso) {
  const [ano, mes, dia] = String(iso).slice(0, 10).split('-');
  return `${dia}/${mes}`;
}

const dias = original.dias_aberta;
const alerta = dias >= 7 ? ' ⚠️' : '';

const legenda = [
  `🗒️ *Pendência — ${original.nome_cliente}*`,
  original.produtos,
  `Responsável: ${original.registrado_por}`,
  `Registrada em ${fmtData(original.data)} (${dias} dia(s) em aberto${alerta})`,
].join('\n');

// signedURL vem relativo ("/object/sign/pendencias/...") do node
// "Gerar link da foto" só quando tinha foto — prefixa pra virar link
// de verdade. Sem foto, fica null (o nó de envio decide mandar texto
// puro nesse caso).
const fotoUrl = item.signedURL ? `https://ggzuchqfepjbsyadfcnk.supabase.co/storage/v1${item.signedURL}` : null;

return { json: { ...original, legenda, fotoUrl } };
